head.script:
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireOver(el);
}
scwin.__hasTooltip = function() {
    if (!WebSquare.wUnit.getDomById($p.id + 'gridView1_tooltip')) {
        return false;
    }
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + "gridView1_tooltip")).getPropertyValue("display") == "block";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 gridView1 의 tooltipDisplay 를 확인한다.
    //1. In the Source tab, check the tooltipDisplay of gridView1.
    //Verify 1. tooltipDisplay='true'
    //Test step 2. tooltipShowAlways 를 확인한다.
    //2. Check tooltipShowAlways.
    //Verify 2. tooltipShowAlways = 'true'
    //Test step 3. 브라우저에서 inputType 이 버튼(button항목)인 컬럼에 마우스오버한다.
    //3. In your browser, hover over the column whose inputType is the button (button item).
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'gridView1_cell_0_3')");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Verify 3. 해당 컬럼의 툴팁이 표시된다. (그전버전에서는 inputType='button' 일 경우 tooltip 이 나오지 않는 현상발생)
    //3. The tooltip for that column is displayed. (In previous versions, if inputType = 'button', tooltip does not appear)
    WebSquare.wUnit.addCommand("assert", "scwin.__hasTooltip()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setData(["hello world hello world", 2, 3, 4, 6, 7, 8, "hello world hello world"]);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
